#!/usr/bin/env python3
"""
distribuir.py
=============
Script auto-contido gerado por build_distributable.py.
Execute em qualquer PC com Python 3.6+ para criar o ZIP do projeto.

Uso:
    python distribuir.py                 # cria projeto.zip no diretorio atual
    python distribuir.py -o outro_nome.zip
"""

import argparse
import base64
import json
import sys
import zipfile
from pathlib import Path

ZIP_DEFAULT = "projeto.zip"
FILE_COUNT  = 55

# Dados dos arquivos (base64-encoded JSON)
_DATA = '{".gemini/commands/sdd/spec-design.toml": "", ".gemini/commands/sdd/spec-impl.toml": "", ".gemini/commands/sdd/spec-init.toml": "", ".gemini/commands/sdd/spec-requirements.toml": "", ".gemini/commands/sdd/spec-status.toml": "", ".gemini/commands/sdd/spec-tasks.toml": "", ".gemini/commands/sdd/steering-custom.toml": "", ".gemini/commands/sdd/steering.toml": "", ".gemini/commands/sdd/validate-design.toml": "", ".gemini/commands/sdd/validate-gap.toml": "", ".gemini/commands/sdd/validate-impl.toml": "", ".github/workflows/ci.yml": "", ".sdd/settings/rules/design-discovery-full.md": "", ".sdd/settings/rules/design-discovery-light.md": "", ".sdd/settings/rules/design-principles.md": "", ".sdd/settings/rules/design-review.md": "", ".sdd/settings/rules/ears-format.md": "", ".sdd/settings/rules/gap-analysis.md": "", ".sdd/settings/rules/steering-principles.md": "", ".sdd/settings/rules/tasks-generation.md": "", ".sdd/settings/rules/tasks-parallel-analysis.md": "", ".sdd/settings/templates/specs/design.md": "", ".sdd/settings/templates/specs/design.pt-br.md": "", ".sdd/settings/templates/specs/init.json": "", ".sdd/settings/templates/specs/requirements-init.md": "IyBSZXF1aXJlbWVudHMgRG9jdW1lbnQKCiMjIFByb2plY3QgRGVzY3JpcHRpb24gKElucHV0KQp7e1BST0pFQ1RfREVTQ1JJUFRJT059fQoKIyMgUmVxdWlyZW1lbnRzCjwhLS0gV2lsbCBiZSBnZW5lcmF0ZWQgaW4gL3NkZDpzcGVjLXJlcXVpcmVtZW50cyBwaGFzZSAtLT4KCgo=", ".sdd/settings/templates/specs/requirements.md": "", ".sdd/settings/templates/specs/requirements.pt-br.md": "", ".sdd/settings/templates/specs/research.md": "", ".sdd/settings/templates/specs/research.pt-br.md": "", ".sdd/settings/templates/specs/tasks.md": "", ".sdd/settings/templates/specs/tasks.pt-br.md": "", ".sdd/settings/templates/steering/product.md": "", ".sdd/settings/templates/steering/structure.md": "", ".sdd/settings/templates/steering/tech.md": "", ".sdd/settings/templates/steering/tech.pt-br.md": "", ".sdd/settings/templates/steering-custom/api-standards.md": "", ".sdd/settings/templates/steering-custom/authentication.md": "", ".sdd/settings/templates/steering-custom/azure-devops.md": "", ".sdd/settings/templates/steering-custom/cross-repo.md": "", ".sdd/settings/templates/steering-custom/database.md": "", ".sdd/settings/templates/steering-custom/deployment.md": "", ".sdd/settings/templates/steering-custom/error-handling.md": "", ".sdd/settings/templates/steering-custom/jira.md": "", ".sdd/settings/templates/steering-custom/security.md": "", ".sdd/settings/templates/steering-custom/testing.md": "", ".sdd/specs/autenticacao-de-usuarios/design.md": "", ".sdd/specs/autenticacao-de-usuarios/requirements.md": "", ".sdd/specs/exemplo-feature/design.md": "", ".sdd/specs/exemplo-feature/requirements.md": "", "CHANGELOG.md": "", "GEMINI.md": "", "GEMINI.pt-br.md": "", "new-spec.ps1": "", "README.md": "", "README.pt-br.md": ""}'


def _decode_files() -> dict:
    return json.loads(_DATA)


def create_zip(dest: Path) -> None:
    files = _decode_files()
    print(f"Criando {dest.name} com {FILE_COUNT} arquivo(s)...")
    print()

    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as zf:
        for rel_path, b64 in files.items():
            data = base64.b64decode(b64)
            zf.writestr(rel_path, data)
            print(f"  [+] {rel_path}")

    size_kb = dest.stat().st_size / 1024
    print()
    print(f"ZIP criado   : {dest.resolve()}")
    print(f"Tamanho      : {size_kb:.1f} KB")
    print(f"Arquivos     : {FILE_COUNT}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Gera o ZIP do projeto.")
    parser.add_argument("-o", "--output", default=ZIP_DEFAULT,
                        help=f"Nome do ZIP de saida (padrao: {ZIP_DEFAULT})")
    args = parser.parse_args()

    dest = Path(args.output)
    if dest.exists():
        resp = input(f"Arquivo '{dest}' ja existe. Sobrescrever? (s/N): ").strip().lower()
        if resp != "s":
            print("Cancelado.")
            sys.exit(0)

    create_zip(dest)


if __name__ == "__main__":
    main()
